mapper.select:
SELECT post_id, user_id, category, title, content, upvote_count, downvote_count, comment_count, created_at, updated_at
FROM post
WHERE post_id = #{postId}

mapper.update:
UPDATE post
SET upvote_count = #{upvoteCount},
    downvote_count = #{downvoteCount}
WHERE post_id = #{postId}

UPDATE post
SET comment_count = #{commentCount}
WHERE post_id = #{postId}
